#[allow(non_snake_case)]
fn call_EventAgenda__vv(
    p0: &TodoPeerScheduleRecord,
    p1: &[TodoPeerValueRecord],
    p2: u64,
    p3: i64,
    p4: i64,
    p5: u32,
) -> Result<Vec<TodoPeerOccurrenceRecord>, sce_forge_runtime::algorithm::AlgorithmError> {
    let p1_algorithm: Vec<mv_value::MvValuePayload> = p1
        .iter()
        .map(|r| mv_value::MvValuePayload {
            id: r.id,
            field: r.field,
            value: r.value,
            text: ::sce_portable_bytes::SceString::<96>::held(&r.text),
            wall_time: r.wallTime,
            counter: r.counter,
            node_id: r.nodeId,
        })
        .collect();
    let r = event_agenda::event_agenda(
        event_schedule::EventSchedulePayload {
            zone: p0.zone,
            start: p0.start,
            length: p0.length,
            freq: p0.freq,
            interval: p0.interval,
            days: p0.days,
            count: p0.count,
            until: p0.until,
            bymonth: p0.bymonth,
            md_pos: p0.mdPos,
            md_neg: p0.mdNeg,
            invalid: p0.invalid,
            op0: p0.op0,
            op1: p0.op1,
            op2: p0.op2,
            op3: p0.op3,
            op4: p0.op4,
            op5: p0.op5,
            op6: p0.op6,
            on0: p0.on0,
            on1: p0.on1,
            on2: p0.on2,
            on3: p0.on3,
            on4: p0.on4,
            on5: p0.on5,
            on6: p0.on6,
            sp_pos: p0.spPos,
            sp_neg: p0.spNeg,
            wkst: p0.wkst,
            wn_pos: p0.wnPos,
            wn_neg: p0.wnNeg,
            yd0: p0.yd0,
            yd1: p0.yd1,
            yd2: p0.yd2,
            yd3: p0.yd3,
            yd4: p0.yd4,
            yd5: p0.yd5,
            ydn0: p0.ydn0,
            ydn1: p0.ydn1,
            ydn2: p0.ydn2,
            ydn3: p0.ydn3,
            ydn4: p0.ydn4,
            ydn5: p0.ydn5,
            gone: p0.gone,
            flag: p0.flag,
        },
        &p1_algorithm,
        p2,
        p3,
        p4,
        p5,
    )?;
    Ok(r.iter()
        .map(|r| TodoPeerOccurrenceRecord {
            id: r.id,
            start: r.start,
            end: r.end,
            nth: r.nth,
            conflict: r.conflict,
        })
        .collect::<Vec<_>>())
}

